function renderDnaPreview(title='DNA · double helix'){const card=document.createElement('section'),heading=document.createElement('h4'),plot=document.createElement('canvas'),c=plot.getContext('2d');card.className='visual-card';heading.textContent=title;plot.width=600;plot.height=260;plot.setAttribute('aria-label','DNA double helix with paired base rungs');c.fillStyle='#17221c';c.fillRect(0,0,plot.width,plot.height);for(let i=0;i<13;i++){const y=28+i*17,x=300+Math.sin(i*Math.PI/3)*90;c.strokeStyle=i%2?'#a9e6b4':'#f2c96d';c.lineWidth=3;c.beginPath();c.moveTo(300-(x-300),y);c.lineTo(x,y);c.stroke();c.fillStyle='#e6eee1';c.font='12px system-ui';c.fillText(i%2?'T · A':'A · T',x<300?330:210,y+4);}for(const color of ['#90c8f4','#f08b83']){c.strokeStyle=color;c.lineWidth=5;c.beginPath();for(let i=0;i<=120;i++){const t=i/120,x=300+Math.sin(t*Math.PI*6)*90*(color==='#90c8f4'?1:-1),y=28+t*204;i?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();}card.append(heading,plot);return card;}
